package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeNumber(long l)
 */
public class TokenBuffer_writeNumber_TriageGen0Test {

    private TokenBuffer tokenBuffer;
    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumberLongPositive() throws IOException {
        long value = 123456789L;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER_INT, tokenBuffer.firstToken());

        // Verify the content by serializing to a generator
        // Since TokenBuffer stores tokens, we check if the sequence is correct
        JsonGenerator gen = mapper.getFactory().createGenerator(new java.io.StringWriter());
        tokenBuffer.serialize(gen);
        gen.flush();

        // We use a second pass to verify the value via a parser
        String json = gen.toString();
        JsonParser parser = mapper.getFactory().createParser(json);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value, parser.getLongValue());
    }








}

